template <class T> __device__ __forceinline__ T warpReduceSum(unsigned int mask, T mySum)
{
    for (int offset = warpSize / 2; offset > 0; offset /= 2) {
        mySum += __shfl_down_sync(mask, mySum, offset);
    }
    return mySum;
}

/*
    Parallel sum reduction using warp collectives, with shared memory only
    for the inter-warp partial sums.
*/
template <class T> __global__ void reduce0(T *g_idata, T *g_odata, unsigned int n)
{
    T *sdata = SharedMemory<T>();

    unsigned int tid = threadIdx.x;
    unsigned int i   = blockIdx.x * blockDim.x + threadIdx.x;
    unsigned int lane = tid % warpSize;
    unsigned int warp = tid / warpSize;
    unsigned int numWarps = (blockDim.x + warpSize - 1) / warpSize;

    // Every launched lane participates; zero padding handles a partial input tile.
    T value = (i < n) ? g_idata[i] : T(0);
    unsigned int mask = __activemask();
    T warpSum = warpReduceSum<T>(mask, value);

    if (lane == 0)
        sdata[warp] = warpSum;

    // Publish the per-warp sums before warp 0 consumes them.
    __syncthreads();

    if (warp == 0) {
        T blockSum = (lane < numWarps) ? sdata[lane] : T(0);
        unsigned int warpMask = __activemask();
        blockSum = warpReduceSum<T>(warpMask, blockSum);
        if (lane == 0)
            g_odata[blockIdx.x] = blockSum;
    }
}


